#include "d2d_private.h"
#include "bitfield.h"
#include "nvfs_usr.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void d2d_code_ena (UInt8 code)
{

  bitfield_wr(d2d_ena_table.d2d_ena  , code , code , D2D_ON);

  nvfs_wr    (nvfs_d2d_ena, &d2d_ena_table) ;
  
  #if DBG_D2D == 1
    TRACE("\nD2D Enable Code: %X" , code) ;
  #endif   
}

